  color: var(--text-secondary);
  line-height: 1.65;
  flex: 1;
}
.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
