  align-items: center;
  gap: 2rem;
}
.logo {
  display: flex;
  align-items: center;
  gap: .45rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: .04em;
  color: var(--text-primary);
  flex-shrink: 0;
