  letter-spacing: .02em;
  transition: background var(--transition), color var(--transition), transform var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: #000;
}
.btn-primary:hover { background: var(--accent-light); }
.btn-primary:active { transform: scale(.97); }
.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-mid);
}
.btn-ghost:hover { background: var(--bg-raised); border-color: var(--text-secondary); }
.btn-sm { padding: .5rem 1rem; font-size: .85rem; }

/* ── Icon button ── */
.icon-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.icon-btn:hover { color: var(--text-primary); background: var(--bg-raised); }

/* ═══════════════════════════════════════════
   HEADER
═══════════════════════════════════════════ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(8,8,8,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 var(--gutter);
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 2rem;
}
.logo {
  display: flex;
  align-items: center;
  gap: .45rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: .04em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.logo-mark { color: var(--accent); }

.primary-nav { flex: 1; display: none; }
@media (min-width: 768px) { .primary-nav { display: block; } }
.primary-nav ul {
  display: flex;
  gap: .25rem;
}
.primary-nav a {
  display: block;
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover { color: var(--text-primary); background: var(--bg-raised); }
.primary-nav a[aria-current="page"] { color: var(--text-primary); }

.header-actions {
  display: flex;
  align-items: center;
  gap: .25rem;
  margin-left: auto;
}
.cart-btn { position: relative; }
.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--accent);
  color: #000;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.nav-toggle { display: flex; flex-direction: column; gap: 4px; }
@media (min-width: 768px) { .nav-toggle { display: none; } }
.hamburger-bar {
  display: block;
  width: 18px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
}

/* Search panel */
.search-panel {
  border-top: 1px solid var(--border);
  background: var(--bg-surface);
  padding: 1rem var(--gutter);
}
.search-panel[hidden] { display: none; }
.search-form {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: .75rem;
}
.search-form input[type="search"] {
  flex: 1;
  background: var(--bg-raised);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  padding: .6rem 1rem;
  font-size: .95rem;
}
.search-form input[type="search"]::placeholder { color: var(--text-muted); }
.search-form input[type="search"]:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 0;
  border-color: transparent;
}

/* Mobile nav */
.mobile-nav {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 1.25rem var(--gutter);
}
.mobile-nav[hidden] { display: none; }
.mobile-nav ul { display: flex; flex-direction: column; gap: .25rem; }
.mobile-nav a {
  display: block;
  padding: .6rem .75rem;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 1rem;
  transition: color var(--transition), background var(--transition);
}
.mobile-nav a:hover { color: var(--text-primary); background: var(--bg-raised); }
.mobile-nav a[aria-current="page"] { color: var(--text-primary); }

/* ═══════════════════════════════════════════
   HERO
═══════════════════════════════════════════ */
.hero {
  position: relative;
  min-height: clamp(480px, 80vh, 820px);
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
}
.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    rgba(8,8,8,.88) 0%,
    rgba(8,8,8,.55) 55%,
    rgba(8,8,8,.2) 100%
  );
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 5rem var(--gutter);
  width: 100%;
}
.hero-content .eyebrow { margin-bottom: 1rem; }
.hero-content h1 {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 6vw, 4.5rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -.02em;
  margin-bottom: 1.25rem;
  max-width: 640px;
}
.hero-sub {
  font-size: clamp(.95rem, 2vw, 1.1rem);
  color: rgba(242,242,242,.75);
  max-width: 480px;
  margin-bottom: 2rem;
  line-height: 1.7;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}

@media (prefers-reduced-motion: no-preference) {
  .hero-bg img {
    animation: hero-zoom 16s ease-in-out infinite alternate;
  }
  @keyframes hero-zoom {
    from { transform: scale(1); }
    to   { transform: scale(1.04); }
  }
}

/* ═══════════════════════════════════════════
   CATEGORY STRIP
═══════════════════════════════════════════ */
.categories {
  border-bottom: 1px solid var(--border);
  padding: 1.1rem var(--gutter);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.categories::-webkit-scrollbar { display: none; }
.categories-list {
  max-width: var(--max-w);
  margin: 0 auto;
  display: flex;
  gap: .6rem;
  flex-wrap: nowrap;
}
.category-chip {
  display: block;
  padding: .4rem 1.1rem;
  border: 1px solid var(--border-mid);
  border-radius: 999px;
  font-size: .83rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all var(--transition);
}
.category-chip:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(200,150,62,.08);
}

/* ═══════════════════════════════════════════
   SECTION COMMONS
═══════════════════════════════════════════ */
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.75rem;
}
.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 400;
  letter-spacing: -.01em;
}
.view-all-link {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: .03em;
  transition: color var(--transition);
  white-space: nowrap;
}
.view-all-link:hover { color: var(--accent-light); }

/* ═══════════════════════════════════════════
   FEATURED PRODUCTS
═══════════════════════════════════════════ */
.featured-products {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 4rem var(--gutter);
}
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.5rem;
}
.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.product-card:hover {
  border-color: var(--border-mid);
  box-shadow: var(--shadow-card);
  transform: translateY(-2px);
}
.product-img-wrap {
  aspect-ratio: 4/5;
  overflow: hidden;
  background: var(--bg-raised);
  position: relative;
}
.product-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 400ms ease;
}
.product-card:hover .product-img-wrap img { transform: scale(1.04); }
.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  background: var(--accent);
  color: #000;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .2rem .55rem;
  border-radius: 4px;
}
.product-body {
  padding: 1rem 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: .35rem;
}
.product-category {
  font-size: .72rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.product-name {
  font-size: .95rem;
  font-weight: 600;
  line-height: 1.35;
}
.product-name a { color: var(--text-primary); transition: color var(--transition); }
.product-name a:hover { color: var(--accent); }
.product-rating {
  display: flex;
  align-items: center;
  gap: .3rem;
  font-size: .78rem;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: -.05em; }
.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: .75rem;
}
.product-price {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-primary);
}
.original-price {
  font-size: .82rem;
  font-weight: 400;
  color: var(--text-muted);
  text-decoration: line-through;
  margin-left: .35rem;
}
.add-to-cart {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--accent);
  color: #000;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition);
}
.add-to-cart:hover { background: var(--accent-light); transform: scale(1.05); }
.add-to-cart:active { transform: scale(.95); }

/* ═══════════════════════════════════════════
   DEALS
═══════════════════════════════════════════ */
.deals-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 4rem 0;
}
.deals-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 var(--gutter);
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
}
@media (min-width: 900px) {
  .deals-inner { grid-template-columns: 340px 1fr; gap: 4rem; align-items: center; }
}
.deals-text .eyebrow { margin-bottom: .75rem; }
.deals-text h2 {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
  font-weight: 400;
  line-height: 1.15;
  margin-bottom: .75rem;
}
.deals-sub { color: var(--text-secondary); font-size: .95rem; margin-bottom: 1.5rem; }
.deal-timer {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-bottom: 1.75rem;
}
.timer-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg-raised);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  padding: .6rem .9rem;
  min-width: 56px;
}
.timer-value {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
}
.timer-label {
  font-size: .65rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-top: .2rem;
}
.timer-colon {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--border-mid);
  line-height: 1;
  margin-bottom: .5rem;
}

.deal-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 1rem;
}
.deal-card {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.deal-card:hover { border-color: var(--border-mid); box-shadow: var(--shadow-card); }
.deal-img-wrap {
  aspect-ratio: 1;
  overflow: hidden;
  background: var(--bg-surface);
  position: relative;
}
.deal-img-wrap img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 400ms ease;
}
.deal-card:hover .deal-img-wrap img { transform: scale(1.04); }
.deal-discount {
  position: absolute;
  top: .6rem; right: .6rem;
  background: var(--red-deal);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  padding: .2rem .5rem;
  border-radius: 4px;
}
.deal-body { padding: .85rem; }
.deal-name { font-size: .9rem; font-weight: 600; margin-bottom: .4rem; line-height: 1.3; }
.deal-name a { color: var(--text-primary); transition: color var(--transition); }
.deal-name a:hover { color: var(--accent); }
.deal-prices { display: flex; align-items: baseline; gap: .5rem; }
.deal-sale { font-size: .95rem; font-weight: 700; color: var(--red-deal); }
.deal-original { font-size: .82rem; color: var(--text-muted); text-decoration: line-through; }

/* ═══════════════════════════════════════════
   EDITORIAL
═══════════════════════════════════════════ */
.editorial-section {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 4rem var(--gutter);
}
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}
.editorial-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.editorial-card:hover {
  border-color: var(--border-mid);
  box-shadow: var(--shadow-card);
  transform: translateY(-2px);
}
.editorial-img-wrap {
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--bg-raised);
}
.editorial-img-wrap img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 500ms ease;
}
.editorial-card:hover .editorial-img-wrap img { transform: scale(1.04); }
.editorial-body { padding: 1.25rem 1.25rem 1.5rem; display: flex; flex-direction: column; flex: 1; }
.editorial-tag {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .6rem;
}
.editorial-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 400;
  line-height: 1.4;
  margin-bottom: .6rem;
}
.editorial-title a { color: var(--text-primary); transition: color var(--transition); }
.editorial-title a:hover { color: var(--accent); }
.editorial-excerpt {
  font-size: .875rem;
  color: var(--text-secondary);
  line-height: 1.65;
  flex: 1;
}
.editorial-meta {
  display: flex;
  align-items: center;
  gap: .6rem;
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
  font-size: .78rem;
  color: var(--text-muted);
  flex-wrap: wrap;
}
.editorial-author { font-weight: 600; color: var(--text-secondary); }

/* ═══════════════════════════════════════════
   NEWSLETTER
═══════════════════════════════════════════ */
.newsletter-section {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 4rem var(--gutter);
}
.newsletter-inner {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
}
.newsletter-inner h2 {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 400;
  margin-bottom: .75rem;
}
.newsletter-sub {
  color: var(--text-secondary);
  font-size: .95rem;
  margin-bottom: 1.75rem;
}
.newsletter-form { text-align: left; }
.newsletter-row {
  display: flex;
  gap: .6rem;
  flex-wrap: wrap;
}
.field-wrap { flex: 1; min-width: 220px; }
.field-wrap label {
  display: block;
  font-size: .85rem;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: .4rem;
}
.required-star { color: var(--accent); }
.field-wrap input[type="email"] {
  width: 100%;
  background: var(--bg-raised);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  padding: .7rem 1rem;
  font-size: .95rem;
  transition: border-color var(--transition);
}
.field-wrap input[type="email"]::placeholder { color: var(--text-muted); }
.field-wrap input[type="email"]:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 0;
  border-color: transparent;
}
.field-wrap input[type="email"][aria-invalid="true"] { border-color: var(--red-deal); }
.newsletter-row .btn { align-self: flex-end; height: 44px; }
.field-error {
  display: block;
  font-size: .8rem;
  color: var(--red-deal);
  min-height: 1.2em;
  margin-top: .3rem;
}
.newsletter-note {
  font-size: .78rem;
  color: var(--text-muted);
  margin-top: .85rem;
  text-align: center;
}
.form-status {
  margin-top: .75rem;
  font-size: .88rem;
  min-height: 1.4em;
  color: var(--green);
  text-align: center;
}

/* ═══════════════════════════════════════════
   FOOTER
═══════════════════════════════════════════ */
.site-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
}
.footer-top {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 3.5rem var(--gutter) 3rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
}
@media (min-width: 640px) {
  .footer-top { grid-template-columns: 240px 1fr; gap: 3rem; }
}
.footer-logo { margin-bottom: .75rem; }
.footer-tagline { font-size: .88rem; color: var(--text-muted); margin-bottom: 1.25rem; max-width: 200px; line-height: 1.6; }
.social-links { display: flex; gap: .5rem; }
.social-links a {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  transition: all var(--transition);
}
.social-links a:hover { color: var(--accent); border-color: var(--accent); background: rgba(200,150,62,.08); }

.footer-nav { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 2rem; }
.footer-col h3 {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: .9rem;
}
.footer-col ul { display: flex; flex-direction: column; gap: .45rem; }
.footer-col a {
  font-size: .875rem;
  color: var(--text-muted);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding: 1.25rem var(--gutter);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  max-width: var(--max-w);
  margin: 0 auto;
}
.copyright { font-size: .8rem; color: var(--text-muted); }
.legal-links { display: flex; flex-wrap: wrap; gap: .1rem; }
.legal-links li { display: flex; align-items: center; }
.legal-links li + li::before { content: "·"; padding: 0 .4rem; color: var(--border-mid); }
.legal-links a { font-size: .8rem; color: var(--text-muted); transition: color var(--transition); }
.legal-links a:hover { color: var(--text-primary); }

/* ═══════════════════════════════════════════
   REFLOW (320 px)
═══════════════════════════════════════════ */
@media (max-width: 420px) {
  .hero-ctas { flex-direction: column; }
  .btn { width: 100%; justify-content: center; }
  .newsletter-row { flex-direction: column; }
  .newsletter-row .btn { width: 100%; }
  .search-form { flex-wrap: wrap; }
}

/* ═══════════════════════════════════════════
   FORCED COLORS (High-Contrast)
═══════════════════════════════════════════ */
@media (forced-colors: active) {
  .hero-overlay { display: none; }
  .cart-badge { border: 2px solid ButtonText; }
  .btn-primary { forced-color-adjust: none; background: Highlight; color: HighlightText; }
  .product-card, .deal-card, .editorial-card { border: 1px solid ButtonText; }
  .product-badge, .deal-discount { forced-color-adjust: none; }
  .category-chip { border: 1px solid ButtonText; }
