/* ─────────────────────────────────────────────
   COUNTDOWN TIMER
   ───────────────────────────────────────────── */

function initTimer() {
  const now = new Date();
  const midnight = new Date(now);
  midnight.setHours(24, 0, 0, 0);

  const hEl = document.getElementById('t-h');
  const mEl = document.getElementById('t-m');
  const sEl = document.getElementById('t-s');
  const srLabel = document.getElementById('timer-sr-label');
  if (!hEl || !mEl || !sEl) return;

  let srUpdateCounter = 0;

  function tick() {
    const diff = Math.max(0, midnight - Date.now());
    const h = Math.floor(diff / 3_600_000);
    const m = Math.floor((diff % 3_600_000) / 60_000);
    const s = Math.floor((diff % 60_000) / 1_000);

    hEl.textContent = pad(h);
    mEl.textContent = pad(m);
    sEl.textContent = pad(s);

    // Update SR live region every 30 seconds to avoid noise
    srUpdateCounter++;
    if (srUpdateCounter >= 30 && srLabel) {
      srLabel.textContent = `Time remaining: ${pad(h)} hours, ${pad(m)} minutes, ${pad(s)} seconds`;
      srUpdateCounter = 0;
    }
  }

  tick();
  setInterval(tick, 1000);
}

/* ─────────────────────────────────────────────
   HEADER – Search panel disclosure
   ───────────────────────────────────────────── */

function initSearch() {
  const btn   = document.getElementById('search-btn');
  const panel = document.getElementById('search-panel');
  const input = document.getElementById('search-input');
  const closeBtn = document.getElementById('close-search');
  if (!btn || !panel) return;

  function open() {
    panel.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    input && input.focus();
  }

  function close() {
    panel.hidden = true;
    btn.setAttribute('aria-expanded', 'false');
    btn.focus();
  }

  btn.addEventListener('click', () => {
    panel.hidden ? open() : close();
  });

  closeBtn && closeBtn.addEventListener('click', close);

  panel.addEventListener('keydown', e => {
    if (e.key === 'Escape') close();
  });
}

/* ─────────────────────────────────────────────
   HEADER – Mobile nav disclosure
   ───────────────────────────────────────────── */

function initMobileNav() {
  const toggle = document.getElementById('nav-toggle');
  const nav    = document.getElementById('mobile-nav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const isOpen = nav.hidden;
    nav.hidden = !isOpen;
    toggle.setAttribute('aria-expanded', String(isOpen));
    toggle.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu');
  });

  // Close on Escape
  nav.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      nav.hidden = true;
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Open navigation menu');
      toggle.focus();
    }
  });
}

/* ─────────────────────────────────────────────
   ADD-TO-CART feedback
   ───────────────────────────────────────────── */

function initCartButtons() {
  document.addEventListener('click', e => {
    const btn = e.target.closest('.add-to-cart');
    if (!btn) return;

    // Brief visual confirmation
    const prev = btn.innerHTML;
    btn.innerHTML = `<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="16" height="16"
         fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
         <polyline points="20 6 9 17 4 12"/></svg>`;
    btn.style.background = 'var(--green)';

    setTimeout(() => {
      btn.innerHTML = prev;
      btn.style.background = '';
    }, 1200);
  });
}

/* ─────────────────────────────────────────────
   NEWSLETTER FORM
   ───────────────────────────────────────────── */

function initNewsletter() {
  const form   = document.getElementById('newsletter-form');
  const input  = document.getElementById('email-input');
  const error  = document.getElementById('email-error');
  const status = document.getElementById('form-status');
  if (!form || !input) return;

  function validateEmail(val) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim());
  }

  form.addEventListener('submit', e => {
    e.preventDefault();
    error.textContent = '';
    input.removeAttribute('aria-invalid');
    status.textContent = '';

    if (!input.value.trim()) {
      error.textContent = 'Please enter your email address.';
      input.setAttribute('aria-invalid', 'true');
      input.focus();
      return;
    }

    if (!validateEmail(input.value)) {
      error.textContent = 'Please enter a valid email address (e.g. you@example.com).';
      input.setAttribute('aria-invalid', 'true');
      input.focus();
