// Calculate contrast between two hex colors
function hexToLum(hex) {
  const r = parseInt(hex.slice(1,3),16)/255;
  const g = parseInt(hex.slice(3,5),16)/255;
  const b = parseInt(hex.slice(5,7),16)/255;
  const lin = c => c <= 0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4);
  return 0.2126*lin(r) + 0.7152*lin(g) + 0.0722*lin(b);
}
function contrast(fg, bg) {
  const [l1,l2] = [hexToLum(fg), hexToLum(bg)].sort((a,b)=>b-a);
  return (l1+0.05)/(l2+0.05);
}
// Find minimum grey that passes 4.5:1 on the harder bg (#111111)
for (let v = 0x00; v <= 0xff; v++) {
  const hex = '#' + v.toString(16).padStart(2,'0').repeat(3);
  const c1 = contrast(hex, '#111111');
  const c2 = contrast(hex, '#1a1a1a');
  if (c1 >= 4.5) {
    console.log('Min passing grey on #111111:', hex, 'contrast on #111:', c1.toFixed(2), 'on #1a1a1a:', c2.toFixed(2));
    break;
  }
}
// Test #888888
console.log('#888 on #111:', contrast('#888888','#111111').toFixed(2));
console.log('#888 on #1a1a1a:', contrast('#888888','#1a1a1a').toFixed(2));
console.log('#7f7f7f on #111:', contrast('#7f7f7f','#111111').toFixed(2));
