   LUMIS – Dark Ecommerce Home Page
   ───────────────────────────────────────────── */

/* ── Design tokens ── */
:root {
  --bg-base:    #080808;
  --bg-surface: #111111;
  --bg-raised:  #1a1a1a;
  --bg-hover:   #222222;
  --border:     #282828;
  --border-mid: #333333;

  --text-primary:   #f2f2f2;
  --text-secondary: #999999;
  --text-muted:     #888888;

  --accent:       #c8963e;
  --accent-light: #e0aa55;
  --accent-dark:  #a87830;

  --red-deal: #e05252;
  --green:    #4caf7d;

  --radius-sm: 6px;
  --radius:    10px;
  --radius-lg: 16px;

  --shadow-card: 0 4px 24px rgba(0,0,0,.45);
  --shadow-up:   0 8px 40px rgba(0,0,0,.6);

  --transition: 200ms ease;
  --font: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-display: Georgia, "Times New Roman", serif;

  --header-h: 64px;
  --max-w: 1280px;
  --gutter: clamp(1rem, 4vw, 2.5rem);
}

/* ── Reset ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { display: block; max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
input, button { outline: none; }

/* ── Screen reader only ── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}
.sr-only:focus,
.sr-only:active {
  position: fixed;
  top: 1rem;
  left: 1rem;
  z-index: 9999;
  width: auto;
  height: auto;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  padding: .6rem 1.2rem;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-up);
}

/* ── Focus ring ── */
:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ── Typography ── */
.eyebrow {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--accent);
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .7rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  letter-spacing: .02em;
  transition: background var(--transition), color var(--transition), transform var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: #000;
}
.btn-primary:hover { background: var(--accent-light); }
.btn-primary:active { transform: scale(.97); }
.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-mid);
}
.btn-ghost:hover { background: var(--bg-raised); border-color: var(--text-secondary); }
.btn-sm { padding: .5rem 1rem; font-size: .85rem; }

/* ── Icon button ── */
.icon-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.icon-btn:hover { color: var(--text-primary); background: var(--bg-raised); }

/* ═══════════════════════════════════════════
   HEADER
 */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(8,8,8,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 var(--gutter);
  height: var(--header-h);
  display: flex;
  align-items: center;
  gap: 2rem;
}
.logo {
  display: flex;
  align-items: center;
  gap: .45rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: .04em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.logo-mark { color: var(--accent); }

.primary-nav { flex: 1; display: none; }
@media (min-width: 768px) { .primary-nav { display: block; } }
.primary-nav ul {
  display: flex;
  gap: .25rem;
}
.primary-nav a {
  display: block;
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.primary-nav a:hover { color: var(--text-primary); background: var(--bg-raised); }
.primary-nav a[aria-current="page"] { color: var(--text-primary); }

.header-actions {
  display: flex;
  align-items: center;
  gap: .25rem;
  margin-left: auto;
}
.cart-btn { position: relative; }
.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--accent);
  color: #000;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.nav-toggle { display: flex; flex-direction: column; gap: 4px; }
@media (min-width: 768px) { .nav-toggle { display: none; } }
.hamburger-bar {
  display: block;
  width: 18px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
}

/* Search panel */
.search-panel {
  border-top: 1px solid var(--border);
  background: var(--bg-surface);
  padding: 1rem var(--gutter);
}
.search-panel[hidden] { display: none; }
.search-form {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: .75rem;
}
.search-form input[type="search"] {
  flex: 1;
  background: var(--bg-raised);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  padding: .6rem 1rem;
  font-size: .95rem;
}
.search-form input[type="search"]::placeholder { color: var(--text-muted); }
.search-form input[type="search"]:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 0;
  border-color: transparent;
}

/* Mobile nav */
.mobile-nav {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 1.25rem var(--gutter);
}
.mobile-nav[hidden] { display: none; }
.mobile-nav ul { display: flex; flex-direction: column; gap: .25rem; }
.mobile-nav a {
  display: block;
  padding: .6rem .75rem;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 1rem;
  transition: color var(--transition), background var(--transition);
}
.mobile-nav a:hover { color: var(--text-primary); background: var(--bg-raised); }
.mobile-nav a[aria-current="page"] { color: var(--text-primary); }

/* ═══════════════════════════
   HERO
 */
.hero {
  position: relative;
  min-height: clamp(480px, 80vh, 820px);
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
}
.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    rgba(8,8,8,.88) 0%,
    rgba(8,8,8,.55) 55%,
    rgba(8,8,8,.2) 100%
  );
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 5rem var(--gutter);
  width: 100%;
}
.hero-content .eyebrow { margin-bottom: 1rem; }
.hero-content h1 {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 6vw, 4.5rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -.02em;
  margin-bottom: 1.25rem;
  max-width: 640px;
}
.hero-sub {
  font-size: clamp(.95rem, 2vw, 1.1rem);
  color: rgba(242,242,242,.75);
  max-width: 480px;
  margin-bottom: 2rem;
  line-height: 1.7;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}

@media (prefers-reduced-motion: no-preference) {
  .hero-bg img {
    animation: hero-zoom 16s ease-in-out infinite alternate;
  }
  @keyframes hero-zoom {
    from { transform: scale(1); }
    to   { transform: scale(1.04); }
  }
}

/* ═════════════════════════
   CATEGORY STRIP
 */
.categories {
  border-bottom: 1px solid var(--border);
  padding: 1.1rem var(--gutter);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.categories::-webkit-scrollbar { display: none; }
.categories-list {
  max-width: var(--max-w);
  margin: 0 auto;
  display: flex;
  gap: .6rem;
  flex-wrap: nowrap;
}
.category-chip {
  display: block;
  padding: .4rem 1.1rem;
  border: 1px solid var(--border-mid);
  border-radius: 999px;
  font-size: .83rem;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  transition: all var(--transition);
}
.category-chip:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(200,150,62,.08);
}

/* ═══════════════════════════════════════════
   SECTION COMMONS
 */
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.75rem;
}
.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 400;
  letter-spacing: -.01em;
}
.view-all-link {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: .03em;
  transition: color var(--transition);
  white-space: nowrap;
}
.view-all-link:hover { color: var(--accent-light); }

/* ═══════════════════════════════════════════
   FEATURED PRODUCTS
 */
.featured-products {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 4rem var(--gutter);
}
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
