/* ── Design tokens ── */
:root {
  --bg-base:    #080808;
  --bg-surface: #111111;
  --bg-raised:  #1a1a1a;
  --bg-hover:   #222222;
  --border:     #282828;
  --border-mid: #333333;

  --text-primary:   #f2f2f2;
  --text-secondary: #999999;
  --text-muted:     #888888;

  --accent:       #c8963e;
  --accent-light: #e0aa55;
  --accent-dark:  #a87830;

  --red-deal: #e05252;
  --green:    #4caf7d;

  --radius-sm: 6px;
  --radius:    10px;
  --radius-lg: 16px;

  --shadow-card: 0 4px 24px rgba(0,0,0,.45);
  --shadow-up:   0 8px 40px rgba(0,0,0,.6);

  --transition: 200ms ease;
  --font: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-display: Georgia, "Times New Roman", serif;

  --header-h: 64px;
  --max-w: 1280px;
  --gutter: clamp(1rem, 4vw, 2.5rem);
}

/* ── Reset ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  background: var(--bg-base);
  color: var(--text-primary);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { display: block; max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
input, button { outline: none; }

/* ── Screen reader only ── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}
.sr-only:focus,
.sr-only:active {
  position: fixed;
  top: 1rem;
  left: 1rem;
  z-index: 9999;
  width: auto;
  height: auto;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  padding: .6rem 1.2rem;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-up);
}

/* ── Focus ring ── */
:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ── Typography ── */
.eyebrow {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--accent);
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .7rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  letter-spacing: .02em;
  transition: background var(--transition), color var(--transition), transform var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: #000;
}
.btn-primary:hover { background: var(--accent-light); }
.btn-primary:active { transform: scale(.97); }
.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-mid);
}
.btn-ghost:hover { background: var(--bg-raised); border-color: var(--text-secondary); }
.btn-sm { padding: .5rem 1rem; font-size: .85rem; }

/* ── Icon button ── */
.icon-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.icon-btn:hover { color: var(--text-primary); background: var(--bg-raised); }

/* ═══════════════════════════════════════════
   HEADER
 */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
