/* 
   UTILITIES
 */   

function fmt(price) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(price);
}

function starsHTML(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return ''.repeat(full) + (half ? '' : '') + ''.repeat(empty);
}

function pad(n) {
  return String(n).padStart(2, '0');
}

/* 
   COMPONENTS  (return HTML strings)
    */

function ProductCard(p) {
  return `
    <li>
      <article class="product-card">
        <div class="product-img-wrap">
          <img src="${p.img}" alt="${p.imgAlt}" width="400" height="500" loading="lazy">
          ${p.badge ? `<span class="product-badge">${p.badge}</span>` : ''}
        </div>
        <div class="product-body">
          <p class="product-category">${p.category}</p>
          <p class="product-name"><a href="#">${p.name}</a></p>
          <p class="product-rating">
            <span class="stars" aria-hidden="true">${starsHTML(p.rating)}</span>
            <span>${p.rating} (${p.reviews})</span>
          </p>
          <div class="product-footer">
            <p class="product-price">${fmt(p.price)}</p>
            <button type="button" class="add-to-cart"
                    aria-label="Add to cart: ${p.name}">
              <svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="16" height="16"
                   fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round">
                <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
              </svg>
            </button>
          </div>
        </div>
      </article>
    </li>`;
}

function DealCard(d) {
  return `
    <li>
      <article class="deal-card">
        <div class="deal-img-wrap">
          <img src="${d.img}" alt="${d.imgAlt}" width="400" height="400" loading="lazy">
          <span class="deal-discount">${d.discount}</span>
        </div>
        <div class="deal-body">
          <p class="deal-name"><a href="#">${d.name}</a></p>
          <div class="deal-prices">
            <span class="deal-sale">${fmt(d.salePrice)}</span>
            <span class="deal-original">${fmt(d.originalPrice)}</span>
          </div>
        </div>
      </article>
    </li>`;
}

function EditorialCard(e) {
  return `
    <li>
      <article class="editorial-card">
        <div class="editorial-img-wrap">
          <img src="${e.img}" alt="${e.imgAlt}" width="800" height="450" loading="lazy">
        </div>
        <div class="editorial-body">
          <p class="editorial-tag">${e.tag}</p>
          <h3 class="editorial-title"><a href="#">${e.title}</a></h3>
          <p class="editorial-excerpt">${e.excerpt}</p>
          <div class="editorial-meta">
            <span class="editorial-author">${e.author}</span>
            <span aria-hidden="true"></span>
            <span>${e.date}</span>
            <span aria-hidden="true"></span>
            <span>${e.readTime}</span>
          </div>
        </div>
      </article>
    </li>`;
}

/* 
   RENDER
 */   

function renderFeatured() {
  const grid = document.getElementById('featured-grid');
  if (!grid) return;
  grid.innerHTML = FEATURED_PRODUCTS.map(ProductCard).join('');
}

function renderDeals() {
  const grid = document.getElementById('deal-grid');
  if (!grid) return;
  grid.innerHTML = DEALS.map(DealCard).join('');
}

function renderEditorial() {
  const grid = document.getElementById('editorial-grid');
  if (!grid) return;
  grid.innerHTML = EDITORIAL.map(EditorialCard).join('');
}

/* 
   COUNTDOWN TIMER
    */

function initTimer() {
  const now = new Date();
  const midnight = new Date(now);
  midnight.setHours(24, 0, 0, 0);

  const hEl = document.getElementById('t-h');
  const mEl = document.getElementById('t-m');
  const sEl = document.getElementById('t-s');
  const srLabel = document.getElementById('timer-sr-label');
  if (!hEl || !mEl || !sEl) return;

  let srUpdateCounter = 0;

  function tick() {
    const diff = Math.max(0, midnight - Date.now());
    const h = Math.floor(diff / 3_600_000);
    const m = Math.floor((diff % 3_600_000) / 60_000);
    const s = Math.floor((diff % 60_000) / 1_000);

    hEl.textContent = pad(h);
    mEl.textContent = pad(m);
    sEl.textContent = pad(s);

    // Update SR live region every 30 seconds to avoid noise
    srUpdateCounter++;
    if (srUpdateCounter >= 30 && srLabel) {
      srLabel.textContent = `Time remaining: ${pad(h)} hours, ${pad(m)} minutes, ${pad(s)} seconds`;
      srUpdateCounter = 0;
    }
  }

  tick();
  setInterval(tick, 1000);
}

/* 
   HEADER  Search panel disclosure
    */

function initSearch() {
  const btn   = document.getElementById('search-btn');
  const panel = document.getElementById('search-panel');
  const input = document.getElementById('search-input');
  const closeBtn = document.getElementById('close-search');
  if (!btn || !panel) return;

  function open() {
    panel.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    input && input.focus();
  }

  function close() {
    panel.hidden = true;
    btn.setAttribute('aria-expanded', 'false');
    btn.focus();
  }

  btn.addEventListener('click', () => {
    panel.hidden ? open() : close();
  });

  closeBtn && closeBtn.addEventListener('click', close);

  panel.addEventListener('keydown', e => {
    if (e.key === 'Escape') close();
  });
}

/* 
   HEADER  Mobile nav disclosure
    */

function initMobileNav() {
  const toggle = document.getElementById('nav-toggle');
  const nav    = document.getElementById('mobile-nav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const isOpen = nav.hidden;
    nav.hidden = !isOpen;
    toggle.setAttribute('aria-expanded', String(isOpen));
    toggle.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu');
  });

  // Close on Escape
  nav.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      nav.hidden = true;
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Open navigation menu');
      toggle.focus();
    }
  });
}

/* 
   ADD-TO-CART feedback
 */   

function initCartButtons() {
  document.addEventListener('click', e => {
    const btn = e.target.closest('.add-to-cart');
    if (!btn) return;

    // Brief visual confirmation
    const prev = btn.innerHTML;
    btn.innerHTML = `<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="16" height="16"
         fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
         <polyline points="20 6 9 17 4 12"/></svg>`;
    btn.style.background = 'var(--green)';

    setTimeout(() => {
      btn.innerHTML = prev;
      btn.style.background = '';
    }, 1200);
  });
}

/* 
   NEWSLETTER FORM
 */   

function initNewsletter() {
  const form   = document.getElementById('newsletter-form');
  const input  = document.getElementById('email-input');
  const error  = document.getElementById('email-error');
  const status = document.getElementById('form-status');
  if (!form || !input) return;

  function validateEmail(val) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim());
  }

  form.addEventListener('submit', e => {
    e.preventDefault();
    error.textContent = '';
    input.removeAttribute('aria-invalid');
    status.textContent = '';

    if (!input.value.trim()) {
      error.textContent = 'Please enter your email address.';
      input.setAttribute('aria-invalid', 'true');
      input.focus();
      return;
    }

    if (!validateEmail(input.value)) {
      error.textContent = 'Please enter a valid email address (e.g. you@example.com).';
      input.setAttribute('aria-invalid', 'true');
      input.focus();
      return;
    }

    // Simulate submission
    status.textContent = "You're subscribed! Welcome to LUMIS.";
    input.value = '';
  });

  // Clear error on input
  input.addEventListener('input', () => {
    if (input.getAttribute('aria-invalid')) {
      error.textContent = '';
      input.removeAttribute('aria-invalid');
    }
  });
}

/* 
   BOOT
 */   

document.addEventListener('DOMContentLoaded', () => {
  renderFeatured();
  renderDeals();
  renderEditorial();
  initTimer();
  initSearch();
  initMobileNav();
  initCartButtons();
  initNewsletter();
});
