/* 
   UTILITIES
 */   

function fmt(price) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(price);
}

function starsHTML(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return ''.repeat(full) + (half ? '' : '') + ''.repeat(empty);
}

function pad(n) {
  return String(n).padStart(2, '0');
}

/* 
   COMPONENTS  (return HTML strings)
    */

function ProductCard(p) {
  return `
    <li>
      <article class="product-card">
        <div class="product-img-wrap">
          <img src="${p.img}" alt="${p.imgAlt}" width="400" height="500" loading="lazy">
          ${p.badge ? `<span class="product-badge">${p.badge}</span>` : ''}
        </div>
        <div class="product-body">
          <p class="product-category">${p.category}</p>
          <p class="product-name"><a href="#">${p.name}</a></p>
          <p class="product-rating">
            <span class="stars" aria-hidden="true">${starsHTML(p.rating)}</span>
            <span>${p.rating} (${p.reviews})</span>
          </p>
          <div class="product-footer">
            <p class="product-price">${fmt(p.price)}</p>
            <button type="button" class="add-to-cart"
                    aria-label="Add to cart: ${p.name}">
              <svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="16" height="16"
                   fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round">
                <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
              </svg>
            </button>
          </div>
        </div>
      </article>
    </li>`;
}

function DealCard(d) {
  return `
    <li>
      <article class="deal-card">
        <div class="deal-img-wrap">
          <img src="${d.img}" alt="${d.imgAlt}" width="400" height="400" loading="lazy">
          <span class="deal-discount">${d.discount}</span>
        </div>
        <div class="deal-body">
          <p class="deal-name"><a href="#">${d.name}</a></p>
          <div class="deal-prices">
            <span class="deal-sale">${fmt(d.salePrice)}</span>
            <span class="deal-original">${fmt(d.originalPrice)}</span>
          </div>
        </div>
      </article>
    </li>`;
}

function EditorialCard(e) {
  return `
